namespace ShipmentTracker.Models;

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Delayed
}

public class Shipment
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime ShippedDate { get; set; }
    public DateTime EstimatedDelivery { get; set; }
    public string CustomerEmail { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public double WeightKg { get; set; }
}

using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Models;

namespace ShipmentTracker.Data;

public class ShipmentDbContext(DbContextOptions<ShipmentDbContext> options) : DbContext(options)
{
    public DbSet<Shipment> Shipments => Set<Shipment>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        base.OnModelCreating(modelBuilder);

        modelBuilder.Entity<Shipment>().HasData(
            new Shipment { Id = 1, TrackingNumber = "TRK-100001", Origin = "New York, US", Destination = "London, UK", Status = ShipmentStatus.InTransit, ShippedDate = new DateTime(2026, 7, 5), EstimatedDelivery = new DateTime(2026, 7, 12), CustomerEmail = "alice@example.com", Description = "Electronics", WeightKg = 2.5 },
            new Shipment { Id = 2, TrackingNumber = "TRK-100002", Origin = "Shanghai, CN", Destination = "Los Angeles, US", Status = ShipmentStatus.Delivered, ShippedDate = new DateTime(2026, 6, 25), EstimatedDelivery = new DateTime(2026, 7, 8), CustomerEmail = "bob@example.com", Description = "Furniture", WeightKg = 45.0 },
            new Shipment { Id = 3, TrackingNumber = "TRK-100003", Origin = "Berlin, DE", Destination = "Tokyo, JP", Status = ShipmentStatus.Pending, ShippedDate = new DateTime(2026, 7, 9), EstimatedDelivery = new DateTime(2026, 7, 18), CustomerEmail = "carol@example.com", Description = "Auto Parts", WeightKg = 12.3 },
            new Shipment { Id = 4, TrackingNumber = "TRK-100004", Origin = "Sydney, AU", Destination = "Mumbai, IN", Status = ShipmentStatus.OutForDelivery, ShippedDate = new DateTime(2026, 7, 2), EstimatedDelivery = new DateTime(2026, 7, 9), CustomerEmail = "dave@example.com", Description = "Medical Supplies", WeightKg = 8.0 },
            new Shipment { Id = 5, TrackingNumber = "TRK-100005", Origin = "São Paulo, BR", Destination = "Toronto, CA", Status = ShipmentStatus.Delayed, ShippedDate = new DateTime(2026, 7, 1), EstimatedDelivery = new DateTime(2026, 7, 14), CustomerEmail = "eve@example.com", Description = "Textiles", WeightKg = 20.0 },
            new Shipment { Id = 6, TrackingNumber = "TRK-100006", Origin = "Dubai, AE", Destination = "Paris, FR", Status = ShipmentStatus.PickedUp, ShippedDate = new DateTime(2026, 7, 8), EstimatedDelivery = new DateTime(2026, 7, 13), CustomerEmail = "frank@example.com", Description = "Jewelry", WeightKg = 0.5 }
        );
    }
}

