using Microsoft.AspNetCore.Authorization;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Data;
using ShipmentTracker.Models;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("/api/shipments");

        // Dispatchers: get all shipments
        group.MapGet("/", [Authorize] async (ShipmentDbContext db) =>
            await db.Shipments.OrderByDescending(s => s.ShippedDate).ToListAsync());

        // Dispatchers: update shipment status
        group.MapPut("/{id:int}/status", [Authorize] async (int id, StatusUpdateRequest request, ShipmentDbContext db) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null) return Results.NotFound();
            shipment.Status = request.Status;
            if (request.EstimatedDelivery.HasValue)
                shipment.EstimatedDelivery = request.EstimatedDelivery.Value;
            await db.SaveChangesAsync();
            return Results.Ok(shipment);
        });

        // Customers: track by tracking number (public)
        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, ShipmentDbContext db) =>
        {
            var shipment = await db.Shipments
                .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
            if (shipment is null) return Results.NotFound();
            return Results.Ok(shipment);
        });

        // Dispatchers: create a new shipment
        group.MapPost("/", [Authorize] async (Shipment shipment, ShipmentDbContext db) =>
        {
            db.Shipments.Add(shipment);
            await db.SaveChangesAsync();
            return Results.Created($"/api/shipments/{shipment.Id}", shipment);
        });
    }
}

public record StatusUpdateRequest(ShipmentStatus Status, DateTime? EstimatedDelivery);

